Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'DISTIPCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &disTipCodigo1.FromString(&GridStateDynamicFilter.Value) If not &disTipCodigo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterdisTipCodigoDescription = format('%1 (%2)', "ID", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterdisTipCodigoDescription = format('%1 (%2)', "ID", "WWP_FilterContains") EndCase &disTipCodigo = &disTipCodigo1 print printBlockFilterdisTipCodigo EndIf Case &DynamicFiltersSelector1 = !'DISTIPDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &disTipDescricao1.FromString(&GridStateDynamicFilter.Value) If not &disTipDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterdisTipDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterdisTipDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &disTipDescricao = &disTipDescricao1 print printBlockFilterdisTipDescricao EndIf Case &DynamicFiltersSelector1 = !'DISTIPDIAS' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &disTipDias1.FromString(&GridStateDynamicFilter.Value) If not &disTipDias1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterdisTipDiasDescription = format('%1 (%2)', "Dias", "=") EndCase &disTipDias = &disTipDias1 print printBlockFilterdisTipDias EndIf Case &DynamicFiltersSelector1 = !'DISTIPNUMERO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &disTipNumero1.FromString(&GridStateDynamicFilter.Value) If not &disTipNumero1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterdisTipNumeroDescription = format('%1 (%2)', "Código", "=") EndCase &disTipNumero = &disTipNumero1 print printBlockFilterdisTipNumero EndIf Case &DynamicFiltersSelector1 = !'DISTIPSTATUS' &disTipStatus1.FromString(&GridStateDynamicFilter.Value) If not &disTipStatus1.IsEmpty() &FilterdisTipStatus1ValueDescription = '' Do Case Case &disTipStatus1.ToString().Trim() = !"A" &FilterdisTipStatus1ValueDescription = "Ativo"
Case &disTipStatus1.ToString().Trim() = !"I" &FilterdisTipStatus1ValueDescription = "Inativo"
EndCase
&FilterdisTipStatusValueDescription = &FilterdisTipStatus1ValueDescription print printBlockFilterdisTipStatus EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'DISTIPCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &disTipCodigo2.FromString(&GridStateDynamicFilter.Value) If not &disTipCodigo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterdisTipCodigoDescription = format('%1 (%2)', "ID", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterdisTipCodigoDescription = format('%1 (%2)', "ID", "WWP_FilterContains") EndCase &disTipCodigo = &disTipCodigo2 print printBlockFilterdisTipCodigo EndIf Case &DynamicFiltersSelector2 = !'DISTIPDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &disTipDescricao2.FromString(&GridStateDynamicFilter.Value) If not &disTipDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterdisTipDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterdisTipDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &disTipDescricao = &disTipDescricao2 print printBlockFilterdisTipDescricao EndIf Case &DynamicFiltersSelector2 = !'DISTIPDIAS' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &disTipDias2.FromString(&GridStateDynamicFilter.Value) If not &disTipDias2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterdisTipDiasDescription = format('%1 (%2)', "Dias", "=") EndCase &disTipDias = &disTipDias2 print printBlockFilterdisTipDias EndIf Case &DynamicFiltersSelector2 = !'DISTIPNUMERO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &disTipNumero2.FromString(&GridStateDynamicFilter.Value) If not &disTipNumero2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterdisTipNumeroDescription = format('%1 (%2)', "Código", "=") EndCase &disTipNumero = &disTipNumero2 print printBlockFilterdisTipNumero EndIf Case &DynamicFiltersSelector2 = !'DISTIPSTATUS' &disTipStatus2.FromString(&GridStateDynamicFilter.Value) If not &disTipStatus2.IsEmpty() &FilterdisTipStatus2ValueDescription = '' Do Case Case &disTipStatus2.ToString().Trim() = !"A" &FilterdisTipStatus2ValueDescription = "Ativo"
Case &disTipStatus2.ToString().Trim() = !"I" &FilterdisTipStatus2ValueDescription = "Inativo"
EndCase
&FilterdisTipStatusValueDescription = &FilterdisTipStatus2ValueDescription print printBlockFilterdisTipStatus EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'DISTIPCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &disTipCodigo3.FromString(&GridStateDynamicFilter.Value) If not &disTipCodigo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterdisTipCodigoDescription = format('%1 (%2)', "ID", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterdisTipCodigoDescription = format('%1 (%2)', "ID", "WWP_FilterContains") EndCase &disTipCodigo = &disTipCodigo3 print printBlockFilterdisTipCodigo EndIf Case &DynamicFiltersSelector3 = !'DISTIPDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &disTipDescricao3.FromString(&GridStateDynamicFilter.Value) If not &disTipDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterdisTipDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterdisTipDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &disTipDescricao = &disTipDescricao3 print printBlockFilterdisTipDescricao EndIf Case &DynamicFiltersSelector3 = !'DISTIPDIAS' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &disTipDias3.FromString(&GridStateDynamicFilter.Value) If not &disTipDias3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterdisTipDiasDescription = format('%1 (%2)', "Dias", "=") EndCase &disTipDias = &disTipDias3 print printBlockFilterdisTipDias EndIf Case &DynamicFiltersSelector3 = !'DISTIPNUMERO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &disTipNumero3.FromString(&GridStateDynamicFilter.Value) If not &disTipNumero3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterdisTipNumeroDescription = format('%1 (%2)', "Código", "=") EndCase &disTipNumero = &disTipNumero3 print printBlockFilterdisTipNumero EndIf Case &DynamicFiltersSelector3 = !'DISTIPSTATUS' &disTipStatus3.FromString(&GridStateDynamicFilter.Value) If not &disTipStatus3.IsEmpty() &FilterdisTipStatus3ValueDescription = '' Do Case Case &disTipStatus3.ToString().Trim() = !"A" &FilterdisTipStatus3ValueDescription = "Ativo"
Case &disTipStatus3.ToString().Trim() = !"I" &FilterdisTipStatus3ValueDescription = "Inativo"
EndCase
&FilterdisTipStatusValueDescription = &FilterdisTipStatus3ValueDescription print printBlockFilterdisTipStatus EndIf EndCase EndIf EndIf EndIf If not &TFdisTipCodigo_Sel.IsEmpty() print printBlockTFdisTipCodigo_Sel Else If not &TFdisTipCodigo.IsEmpty() print printBlockTFdisTipCodigo EndIf EndIf If not &TFdisTipDescricao_Sel.IsEmpty() print printBlockTFdisTipDescricao_Sel Else If not &TFdisTipDescricao.IsEmpty() print printBlockTFdisTipDescricao EndIf EndIf If not &TFdisTipDescricaoPlural_Sel.IsEmpty() print printBlockTFdisTipDescricaoPlural_Sel Else If not &TFdisTipDescricaoPlural.IsEmpty() print printBlockTFdisTipDescricaoPlural EndIf EndIf If not (&TFdisTipDias.IsEmpty() AND &TFdisTipDias_To.IsEmpty()) print printBlockTFdisTipDias &TFdisTipDias_To_Description = format('%1 (%2)', "Dias", "WWP_TSTo") print printBlockTFdisTipDias_To EndIf If not (&TFdisTipSemanas.IsEmpty() AND &TFdisTipSemanas_To.IsEmpty()) print printBlockTFdisTipSemanas &TFdisTipSemanas_To_Description = format('%1 (%2)', "Semanas", "WWP_TSTo") print printBlockTFdisTipSemanas_To EndIf If not (&TFdisTipRemessaMes.IsEmpty() AND &TFdisTipRemessaMes_To.IsEmpty()) print printBlockTFdisTipRemessaMes &TFdisTipRemessaMes_To_Description = format('%1 (%2)', "Remessas no Mês", "WWP_TSTo") print printBlockTFdisTipRemessaMes_To EndIf &TFdisTipStatus_Sels.FromJson(&TFdisTipStatus_SelsJson) If not &TFdisTipStatus_Sels.Count = 0 &i = 1 For &TFdisTipStatus_Sel in &TFdisTipStatus_Sels If &i = 1 &TFdisTipStatus_SelDscs = '' Else &TFdisTipStatus_SelDscs += ', ' EndIf &FilterTFdisTipStatus_SelValueDescription = '' Do Case Case &TFdisTipStatus_Sel.ToString().Trim() = !"A" &FilterTFdisTipStatus_SelValueDescription = "Ativo"
Case &TFdisTipStatus_Sel.ToString().Trim() = !"I" &FilterTFdisTipStatus_SelValueDescription = "Inativo"
EndCase
&TFdisTipStatus_SelDscs += &FilterTFdisTipStatus_SelValueDescription &i += 1 EndFor print printBlockTFdisTipStatus_Sel EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsdistribuicaotipo order disTipCodigo when &OrderedBy = 1 AND &OrderedDsc = False order (disTipCodigo) when &OrderedBy = 1 AND &OrderedDsc = True order disTipDescricao when &OrderedBy = 2 AND &OrderedDsc = False order (disTipDescricao) when &OrderedBy = 2 AND &OrderedDsc = True order disTipDescricaoPlural when &OrderedBy = 3 AND &OrderedDsc = False order (disTipDescricaoPlural) when &OrderedBy = 3 AND &OrderedDsc = True order disTipDias when &OrderedBy = 4 AND &OrderedDsc = False order (disTipDias) when &OrderedBy = 4 AND &OrderedDsc = True order disTipSemanas when &OrderedBy = 5 AND &OrderedDsc = False order (disTipSemanas) when &OrderedBy = 5 AND &OrderedDsc = True order disTipRemessaMes when &OrderedBy = 6 AND &OrderedDsc = False order (disTipRemessaMes) when &OrderedBy = 6 AND &OrderedDsc = True order disTipStatus when &OrderedBy = 7 AND &OrderedDsc = False order (disTipStatus) when &OrderedBy = 7 AND &OrderedDsc = True
using trnsdistribuicaotipoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &disTipCodigo1, &disTipDescricao1, &disTipDias1, &disTipNumero1 , &disTipStatus1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &disTipCodigo2, &disTipDescricao2 , &disTipDias2, &disTipNumero2, &disTipStatus2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &disTipCodigo3, &disTipDescricao3, &disTipDias3, &disTipNumero3, &disTipStatus3, &TFdisTipCodigo , &TFdisTipCodigo_Sel, &TFdisTipDescricao, &TFdisTipDescricao_Sel, &TFdisTipDescricaoPlural, &TFdisTipDescricaoPlural_Sel, &TFdisTipDias , &TFdisTipDias_To, &TFdisTipSemanas, &TFdisTipSemanas_To, &TFdisTipRemessaMes, &TFdisTipRemessaMes_To, &TFdisTipStatus_Sels) Where prefCodigo = &prefCodigo &disTipStatusDescription = '' Do Case Case disTipStatus.ToString().Trim() = !"A" &disTipStatusDescription = "Ativo"
Case disTipStatus.ToString().Trim() = !"I" &disTipStatusDescription = "Inativo"
EndCase
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsdistribuicaotipoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsdistribuicaotipoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsdistribuicaotipoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFDISTIPCODIGO" &TFdisTipCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTIPCODIGO_SEL" &TFdisTipCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTIPDESCRICAO" &TFdisTipDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTIPDESCRICAO_SEL" &TFdisTipDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTIPDESCRICAOPLURAL" &TFdisTipDescricaoPlural.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTIPDESCRICAOPLURAL_SEL" &TFdisTipDescricaoPlural_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFDISTIPDIAS" &TFdisTipDias.FromString(&GridStateFilterValue.Value) &TFdisTipDias_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTIPSEMANAS" &TFdisTipSemanas.FromString(&GridStateFilterValue.Value) &TFdisTipSemanas_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTIPREMESSAMES" &TFdisTipRemessaMes.FromString(&GridStateFilterValue.Value) &TFdisTipRemessaMes_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFDISTIPSTATUS_SEL" &TFdisTipStatus_SelsJson = &GridStateFilterValue.Value &TFdisTipStatus_Sels.FromJson(&TFdisTipStatus_SelsJson) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
